305	// Load reads the registry at path. A missing file yields an empty registry
306	// with existed == false. An existing file that is empty, not parseable as
307	// the public format — including missing, null, duplicated, misspelled or
308	// mistyped fields — of an unsupported version, or holding duplicate batch
309	// ids is an error: callers must never overwrite such a file as if it were a
310	// fresh registry.
311	func Load(path string) (reg *Registry, existed bool, err error) {
312		data, err := os.ReadFile(path)
313		if err != nil {
314			if errors.Is(err, fs.ErrNotExist) {
315				return &Registry{Version: FormatVersion}, false, nil
316			}
317			return nil, false, fmt.Errorf("cannot read registry %q: %w", path, err)
318		}
319		if len(bytes.TrimSpace(data)) == 0 {
320			return nil, true, fmt.Errorf("registry file %q is empty; refusing to replace it with a new registry", path)
321		}
322		reg, err = decode(data)
323		if err != nil {
324			return nil, true, fmt.Errorf("cannot parse registry %q as version %d JSON: %w", path, FormatVersion, err)
325		}
326		if err := validate(reg); err != nil {
327			return nil, true, fmt.Errorf("registry %q is not usable: %w", path, err)
328		}
329		return reg, true, nil
330	}
331	
332	// decode parses data as the public registry format. The root must be a JSON
333	// object holding exactly "version" (the integer 1) and "batches" (an array,
334	// possibly empty); every record must be an object holding exactly "batch",
335	// "product", "quantity" and "unit". Field names are matched case-sensitively
336	// after JSON string decoding, so "Version" or "Batch" are unknown fields and
337	// an escaped respelling such as "bat\u0063h" counts as the same field. A
338	// field appearing twice in one object is rejected even when both values are
339	// identical; missing fields, nulls, wrong types and unknown fields are
340	// rejected just the same. Nothing is patched up by taking the later value,
341	// merging or defaulting.
342	func decode(data []byte) (*Registry, error) {
343		dec := json.NewDecoder(bytes.NewReader(data))
344		var root json.RawMessage
345		if err := dec.Decode(&root); err != nil {
346			return nil, err
347		}
348		var extra json.RawMessage
349		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
350			if err == nil {
351				return nil, errors.New("unexpected data after registry object")
352			}
353			return nil, err
354		}
355	
356		fields, err := parseObjectFields(root)
357		if err != nil {
358			return nil, &FormatError{Reason: "root must be a JSON object holding exactly \"version\" and \"batches\""}
359		}
360		if dup, ok := duplicateField(fields); ok {
361			return nil, &FormatError{Field: dup, Reason: "field appears more than once; duplicate fields are not allowed"}
362		}
363		for _, f := range fields {
364			if f.key != "version" && f.key != "batches" {
365				return nil, &FormatError{Field: f.key, Reason: "unknown field; only \"version\" and \"batches\" are allowed"}
366			}
367		}
368		versionRaw, ok := findField(fields, "version")
369		if !ok {
370			return nil, &FormatError{Field: "version", Reason: "required field is missing"}
371		}
372		batchesRaw, ok := findField(fields, "batches")
373		if !ok {
374			return nil, &FormatError{Field: "batches", Reason: "required field is missing"}
375		}
376		version, err := parseRegistryVersion(versionRaw)
377		if err != nil {
378			return nil, err
379		}
380		if trimmed := bytes.TrimSpace(batchesRaw); len(trimmed) == 0 || trimmed[0] != '[' {
381			return nil, &FormatError{Field: "batches", Reason: "must be an array of batch records"}
382		}
383		var elems []json.RawMessage
384		if err := json.Unmarshal(batchesRaw, &elems); err != nil {
385			return nil, &FormatError{Field: "batches", Reason: "must be an array of batch records"}
386		}
387		reg := &Registry{Version: version, Batches: make([]Batch, 0, len(elems))}
388		for i, raw := range elems {
389			b, err := parseRegistryRecord(raw, i+1)
390			if err != nil {
391				return nil, err
392			}
393			reg.Batches = append(reg.Batches, b)
394		}
395		return reg, nil
396	}
