639	// ManifestConflictError reports that a manifest record disagrees with the
640	// record already registered, or introduced earlier in the same manifest,
641	// under the same batch id. Position is the record's 1-based position in the
642	// manifest and Fields lists every differing member among "product",
643	// "quantity" and "unit" in that order.
644	type ManifestConflictError struct {
645		Position int
646		Batch    string
647		Fields   []string
648		Source   string // "registry" or "manifest"
649		PrevPos  int    // 1-based position of the earlier manifest record, if Source == "manifest"
650	}
651	
652	func (e *ManifestConflictError) Error() string {
653		if e.Source == "manifest" {
654			return fmt.Sprintf("manifest record %d (batch %q) conflicts with manifest record %d on field(s): %s; the whole manifest is rejected",
655				e.Position, e.Batch, e.PrevPos, strings.Join(e.Fields, ", "))
656		}
657		return fmt.Sprintf("manifest record %d (batch %q) conflicts with the registered record on field(s): %s; the whole manifest is rejected",
658			e.Position, e.Batch, strings.Join(e.Fields, ", "))
659	}
