					t.Fatalf("rejected save must not create the target, stat err=%v", statErr)
				}
				assertNoTempFiles(t, dir)
			})

			if len(reg.Batches) != 2 || reg.Batches[0] != good {
				t.Fatalf("rejected save mutated the caller's registry: %+v", reg.Batches)
			}
		})
	}
